<?php require_once 'config/database.php'; require_once 'includes/auth.php'; require_login(); $stmt=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY order_date DESC'); $stmt->execute([$_SESSION['user']['id']]); $orders=$stmt->fetchAll(); $page_title='My Orders'; include 'includes/header.php'; ?><section class="page-banner"><div class="container"><div class="eyebrow">Your FoodNest activity</div><h1>My Orders</h1></div></section><section class="section"><div class="container"><?php if(!$orders): ?><div class="empty"><h2>No orders yet.</h2><a class="button" href="menu.php">Browse Menu</a></div><?php else: foreach($orders as $order): ?><article class="order-card"><div class="order-top"><strong>Order #<?= $order['id'] ?></strong><span class="status"><?= esc($order['order_status']) ?></span></div><p class="muted"><?= date('d M Y, h:i A',strtotime($order['order_date'])) ?> &middot; <?= esc($order['payment_method']) ?></p><p>Total: <strong>₹<?= number_format($order['total_amount'],2) ?></strong></p><details><summary>View Details</summary><?php $items=$pdo->prepare('SELECT oi.*,f.food_name FROM order_items oi JOIN foods f ON f.id=oi.food_id WHERE oi.order_id=?'); $items->execute([$order['id']]); ?><ul><?php foreach($items as $item): ?><li><?= esc($item['food_name']) ?> &times; <?= $item['quantity'] ?> - ₹<?= number_format($item['price']*$item['quantity'],2) ?></li><?php endforeach; ?></ul><p class="muted">Deliver to: <?= esc($order['delivery_address']) ?></p></details></article><?php endforeach; endif; ?></div></section><?php include 'includes/footer.php'; ?>